let dbData = $input.all();

if (dbData.length === 0 || Object.keys(dbData[0].json).length === 0) {
    return [{ json: { hasil: "Data tidak ditemukan di database ERP untuk pencarian tersebut. Beritahu pengguna dengan sopan." } }];
}

let hasil_teks = "Berikut adalah data yang ditemukan dari database ERP:\n";

dbData.forEach((row, index) => {
    let item = row.json;
    hasil_teks += (index + 1) + ". Nama Barang: " + (item.item_name || item.name || "-") + "\n";
    hasil_teks += "   Kode BOM: " + (item.item_code || "-") + "\n";
    hasil_teks += "   Dimensi: " + (item.dimension || "-") + "\n";
    hasil_teks += "   Material: " + (item.material || "-") + "\n\n";
});

// Mengembalikan teks mentah ke AI agar AI bisa membacanya dan merangkainya menjadi kalimat natural
return [{ json: { hasil: hasil_teks } }];
